import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"平台简介与核心概念","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":null}'),n={name:"guide/introduction.md"};function o(s,t,l,i,g,h){return r(),a("div",null,[...t[0]||(t[0]=[e(`<h1 id="平台简介与核心概念" tabindex="-1">平台简介与核心概念 <a class="header-anchor" href="#平台简介与核心概念" aria-label="Permalink to &quot;平台简介与核心概念&quot;">​</a></h1><h2 id="什么是-northstar" tabindex="-1">什么是 Northstar <a class="header-anchor" href="#什么是-northstar" aria-label="Permalink to &quot;什么是 Northstar&quot;">​</a></h2><p><strong>Northstar（盈富量化交易平台）</strong> 是一个基于 Java + Spring Boot 的量化交易平台，提供模块化的策略开发、历史回放（回测）、模拟交易和实盘部署能力。前端为 Vue 3 单页应用，通过浏览器访问，桌面端与移动端均可使用。</p><p>平台覆盖量化交易的完整链路：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>历史行情 → 历史回放（回测/复盘） → 模拟盘验证 → 实盘程序化交易</span></span>
<span class="line"><span>                ↑                        ↑</span></span>
<span class="line"><span>           操盘手训练 ←——— 手工交易练习 ←——┘</span></span></code></pre></div><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><p>以下术语来自平台首页的&quot;术语解释&quot;，理解它们是使用平台的前提：</p><table tabindex="0"><thead><tr><th>术语</th><th>说明</th></tr></thead><tbody><tr><td><strong>网关（Gateway）</strong></td><td>代表一个能与外部接口建立连接的组件，是平台连接一切外部能力的入口</td></tr><tr><td><strong>行情网关</strong></td><td>能接收实时行情数据的网关（用途 = 行情 MARKET_DATA）</td></tr><tr><td><strong>交易网关</strong></td><td>能发送交易委托进行账户交易的网关（用途 = 交易 TRADE），<strong>一个交易网关对应一个实际的交易账户</strong></td></tr><tr><td><strong>合约（Contract）</strong></td><td>可交易的标准化品种，合约由行情网关订阅后才能在平台内使用</td></tr><tr><td><strong>交易策略（Strategy）</strong></td><td>一段可执行的交易逻辑代码（Java 类），定义了何时开仓、何时平仓</td></tr><tr><td><strong>模组（Module）</strong></td><td>自动化交易的运行单元，定义了&quot;<strong>哪个策略</strong>在<strong>哪个账户</strong>上对<strong>哪个品种</strong>进行交易&quot;</td></tr><tr><td><strong>模组账户</strong></td><td>每个模组内部的逻辑账本，与实际交易账户没有直接映射关系；模组账户的余额与持仓决定了交易算法能否开平仓</td></tr></tbody></table><h2 id="网关渠道与用途" tabindex="-1">网关渠道与用途 <a class="header-anchor" href="#网关渠道与用途" aria-label="Permalink to &quot;网关渠道与用途&quot;">​</a></h2><p>创建网关时需要选择<strong>渠道</strong>（连接哪类外部系统）与<strong>用途</strong>（行情 or 交易）：</p><table tabindex="0"><thead><tr><th>渠道</th><th style="text-align:center;">行情</th><th style="text-align:center;">交易</th><th>说明</th></tr></thead><tbody><tr><td><strong>PLAYBACK</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td><td>历史回放（内置），详见 <a href="/features/playback">历史回放</a></td></tr><tr><td><strong>SIM</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td>模拟撮合（内置，零配置），详见 <a href="/features/sim-trading">模拟盘交易</a></td></tr><tr><td><strong>CTP</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td>期货实盘（由外部网关 jar 提供）</td></tr><tr><td><strong>CTP_SIM</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td>CTP 仿真环境（仅超级用户模式可见）</td></tr><tr><td><strong>TIGER / OKX / BIAN</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td>老虎证券 / OKX / 币安（由外部网关 jar 提供）</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>本发行版内置 <strong>PLAYBACK</strong> 与 <strong>SIM</strong> 两个渠道，开箱即可进行回放、回测与模拟交易。CTP 等实盘渠道通过将网关 jar 放置于程序同级目录（启动脚本 <code>startup.sh</code> 通过 <code>-Dloader.path</code> 加载）后注册使用。</p></div><h2 id="模组用途" tabindex="-1">模组用途 <a class="header-anchor" href="#模组用途" aria-label="Permalink to &quot;模组用途&quot;">​</a></h2><p>模组有三种用途，对应量化策略生命周期的三个阶段：</p><table tabindex="0"><thead><tr><th>模组用途</th><th>说明</th></tr></thead><tbody><tr><td><strong>回测（PLAYBACK）</strong></td><td>绑定回放环境，在历史行情上验证策略表现</td></tr><tr><td><strong>模拟盘（UAT）</strong></td><td>绑定 SIM 模拟账户，在实时仿真行情中试运行策略</td></tr><tr><td><strong>实盘（PROD）</strong></td><td>绑定 CTP 等实盘账户，真实资金自动交易</td></tr></tbody></table><h2 id="主要功能菜单一览" tabindex="-1">主要功能菜单一览 <a class="header-anchor" href="#主要功能菜单一览" aria-label="Permalink to &quot;主要功能菜单一览&quot;">​</a></h2><p>平台左侧菜单（按顺序）：</p><table tabindex="0"><thead><tr><th>菜单</th><th>子菜单</th><th>用途</th></tr></thead><tbody><tr><td><strong>首页</strong></td><td>—</td><td>快捷键参考、术语解释、已购服务</td></tr><tr><td><strong>网关管理</strong></td><td>—</td><td>创建/连接/管理行情与交易网关（账户）</td></tr><tr><td><strong>交易中心</strong></td><td>活跃行情报价</td><td>实时行情报价表，可按行情网关筛选</td></tr><tr><td></td><td>多图同列</td><td>多周期多品种 K 线图，回放与画线交易的主战场（仅桌面端）</td></tr><tr><td></td><td>移动端图表</td><td>移动端 K 线图（仅移动端显示）</td></tr><tr><td></td><td>期权日历</td><td>期权到期日查询</td></tr><tr><td><strong>合约配置</strong></td><td>—</td><td>按合约设置杠杆、手续费、交易时段，支持导入导出</td></tr><tr><td><strong>交易自动化</strong></td><td>模组管理</td><td>创建/启停/监控程序化交易模组</td></tr><tr><td></td><td>策略探索</td><td>批量回测：一个策略 × 多个合约的参数寻优</td></tr><tr><td><strong>日志中心</strong></td><td>平台日志</td><td>平台运行日志</td></tr><tr><td></td><td>模组日志</td><td>按模组查看策略输出日志</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">移动端说明</p><p>&quot;多图同列&quot;等重交互页面仅桌面端可用；移动端提供专门的图表与模组管理视图。建议日常操盘使用桌面浏览器访问。</p></div>`,19)])])}const u=d(n,[["render",o]]);export{p as __pageData,u as default};
